def residual(G,m):return G.subgraph([v for v in G if m>>v&1])
def independent_other(G,m):return all((m>>u&1)or(m>>v&1) for u,v in G.edges)
def allowed(G,typ):
 for C in nx.connected_components(G):
  H=G.subgraph(C);n=len(C)
  if typ=='M' and n>2:return False
  if typ=='T' and n>3:return False # any graph<=3 embeds K3
  if typ=='C' and (n>4 or not nx.is_bipartite(H) or max(dict(H.degree()).values(),default=0)>2):return False
 return True
for G in nx.graph_atlas_g():
 n=len(G)
 if nx.is_bipartite(G): continue
 if not any(nx.is_bipartite(G.subgraph([u for u in G if u!=v])) for v in G):continue
 feats=set()
 for m in range(1<<n):
  if not independent_other(G,m):continue
  A=residual(G,m)
  for typ in ['M','T','C']:
   if allowed(A,typ):feats.add(typ)
 if 'T'in feats and'C'in feats and'M' not in feats:
  print('counterexample',n,list(G.edges));break
else:print('none up to7')

