import random,networkx as nx,time
rng=random.Random(1)
def embtypes(G):
 n=len(G); adj=[sum(1<<w for w in G[v]) for v in G];allmask=(1<<n)-1
 found=set()
 for m in range(1<<n):
  B=allmask^m
  if any(adj[v]&B for v in range(n) if B>>v&1):continue
  verts=[v for v in range(n) if m>>v&1]
  ds={v:(adj[v]&m).bit_count() for v in verts}
  if max(ds.values(),default=0)>2:continue
  comps=[];unseen=m
  while unseen:
   todo=unseen&-unseen;c=0
   while todo:
    b=todo&-todo;todo^=b;v=b.bit_length()-1;c|=b;unseen&=~b
    todo|=adj[v]&m&~c
   vs=[v for v in verts if c>>v&1];comps.append((len(vs),sum(ds[v] for v in vs)//2))
  if all(k<=3 for k,e in comps):found.add('T')
  if all(e<k for k,e in comps):found.add('L')
  if all(k<=3 and e<k for k,e in comps):return {'P'} # implies T,L
 return found
start=time.time()
for trial in range(50000):
 n=rng.choice([8,9,10]);a=(n-1)//2;b=n-1-a
 G=nx.Graph();G.add_nodes_from(range(n))
 for u in range(a):
  for v in range(a,n-1):
   if rng.random()<.6:G.add_edge(u,v)
 for u in range(n-1):
  if rng.random()<.8:G.add_edge(u,n-1)
 if nx.is_bipartite(G):continue
 ty=embtypes(G)
 if ty=={'T','L'}:
  print('COUNTER',n,list(G.edges),trial);break
else: print('no random counterexamples',trial+1)
print('seconds',time.time()-start)

