import random,time,networkx as nx,z3
rng=random.Random(12224)
def constraints(G):
 n=len(G);a=[z3.Bool('a'+str(i)) for i in range(n)]
 base=[z3.Or(a[u],a[v]) for u,v in G.edges]+[z3.Implies(a[u],z3.PbLe([(a[w],1) for w in G[u]],2)) for u in G]
 tri=set();c4=set();p5=set()
 for u in G:
  for v in G[u]:
   for w in G[v]:
    if w==u:continue
    if G.has_edge(u,w):tri.add(frozenset((u,v,w)))
    for x in G[w]:
     if x in (u,v):continue
     if G.has_edge(x,u):c4.add(frozenset((u,v,w,x)))
     for y in G[x]:
      if y not in (u,v,w):p5.add(frozenset((u,v,w,x,y)))
 def clause(S):return z3.Or([z3.Not(a[u]) for u in S])
 small=[clause(S) for S in tri|p5];four=[clause(S) for S in c4]
 return a,base,small,four
start=time.time();trials=0;counter=0
for trial in range(1000):
 q=3;bsize=8;n=3+3*q+bsize;v=0;A=list(range(3+3*q));B=list(range(3+3*q,n));G=nx.Graph();G.add_nodes_from(range(n));G.add_edges_from([(0,1),(1,2),(2,0)]);color={1:0,2:1}
 for j in range(q):
  x=3+3*j;c=rng.randrange(2);color[x]=c;color[x+1]=color[x+2]=1-c;G.add_edges_from([(x,x+1),(x,x+2)])
 for j,u in enumerate(B):color[u]=j%2
 for x in A[1:]:
  for y in B:
   if color[x]!=color[y] and rng.random()<.6:G.add_edge(x,y)
 for y in B:
  if rng.random()<.7:G.add_edge(0,y)
 a,base,small,four=constraints(G)
 s=z3.Solver();s.add(base+small+four)
 if s.check()!=z3.unsat:continue
 counter+=1
 s=z3.Solver();s.add(base+small)
 if s.check()!=z3.sat:continue
 # find forest partition via cycle cuts
 sl=z3.Solver();sl.add(base)
 while sl.check()==z3.sat:
  m=sl.model();AA=[u for u in G if z3.is_true(m.eval(a[u]))];cy=nx.cycle_basis(G.subgraph(AA))
  if not cy:
   print('COUNTERCLOSURE',trial,n,list(G.edges),flush=True);raise SystemExit
  for C in cy:sl.add(z3.Or([z3.Not(a[u]) for u in C]))
 trials+=1
 if trial%50==0:print(trial,'p4free',counter,'c4satLfreechecks',trials,'time',time.time()-start,flush=True)
print('none',counter,trials,time.time()-start)

